const inputData = $input.first().json.body || $input.first().json;

const query = inputData.message || inputData.query || inputData.text || '';
const userEmail = inputData.email || inputData.userEmail || 'employee@company.com';
const userName = inputData.name || inputData.userName || 'Employee';

if (!query.trim()) {
  throw new Error("[Validation Error] Message không được để trống!");
}

return {
  query,
  userEmail,
  userName,
  timestamp: new Date().toISOString()
};

