const prev = $('Validate Input Query').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    needTicket: true,
    replyMessage: "Hệ thống đã ghi nhận sự cố của bạn và chuyển cho kỹ thuật viên IT.",
    ticketTitle: prev.query.slice(0, 50),
    ticketDescription: prev.query,
    category: "Other",
    priority: "Medium"
  };
}

const ticketId = `TCK-${Math.floor(100000 + Math.random() * 900000)}`;

return {
  userEmail: prev.userEmail,
  userName: prev.userName,
  query: prev.query,
  needTicket: !!parsed.needTicket,
  replyMessage: parsed.replyMessage || "Đã tiếp nhận yêu cầu.",
  ticketId,
  ticketTitle: parsed.ticketTitle || prev.query,
  ticketDescription: parsed.ticketDescription || prev.query,
  category: parsed.category || "Other",
  priority: parsed.priority || "Medium",
  status: "Open",
  createdAt: new Date().toISOString()
};
